using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.UIElements;

namespace JamKit.Shell
{
    /// <summary>
    /// The shell's own UI and input assets, generated by "JamKit/Rebuild Shell Scenes" into
    /// Assets/JamKit/Resources/JamKit/ShellAssets.asset. Teams normally edit the UXML/USS files it
    /// points to, not this asset.
    /// </summary>
    public sealed class ShellAssets : ScriptableObject
    {
        public const string ResourcePath = "JamKit/ShellAssets";

        public PanelSettings panelSettings;
        [Tooltip("Theme.uss (colours and sizes as variables) then Shell.uss (layout).")]
        public List<StyleSheet> styleSheets = new List<StyleSheet>();
        public InputActionAsset input;

        [Header("Screens")]
        public VisualTreeAsset title;
        public VisualTreeAsset settings;
        public VisualTreeAsset pause;
        public VisualTreeAsset gameOver;
        public VisualTreeAsset victory;
        public VisualTreeAsset credits;
        public VisualTreeAsset howToPlay;
        public VisualTreeAsset hud;
        public VisualTreeAsset dialogue;
        public VisualTreeAsset debugMenu;
    }
}
